insert into public.tenants (id, slug, name, config, private_config) values ('a0000000-0000-4000-8000-000000000001', 'kadam-hospital', 'Kadam Hospital Accident & Orthopedic', '{"short_name":"Kadam Hospital","short_name_mr":"कदम हॉस्पिटल","tagline":"Accident, Trauma & Orthopaedic Care — Shrirampur","tagline_mr":"अपघात, ट्रॉमा व अस्थिरोग उपचार — श्रीरामपूर","address":"Near Anarase Hospital, Belapur Road, Raskar Nagar (near MHADA Colony), Ward No. 7, Shrirampur MIDC, Dist. Ahmednagar, Maharashtra 413709","phone":"+91 90110 22349","whatsapp":"+91 90110 22349","emergency_24x7":true,"opd_hours_text":"Mon–Sat 10:00 AM–2:00 PM and 5:00–8:00 PM · Sunday OPD closed","opd_hours_text_mr":"सोम–शनि सकाळी १०–दुपारी २ व सायं. ५–रात्री ८ · रविवारी ओपीडी बंद","languages":["Marathi","Hindi","English"],"google_maps_url":null,"accent_color":"#0A84FF","timezone":"Asia/Kolkata","booking_window_days":7,"token_prefix":"KH","auto_confirm":true,"retention_months":12,"demo":true,"facilities":[{"en":"Open 24 hours","mr":"२४ तास सुरू","icon":"clock"},{"en":"Wheelchair accessible","mr":"व्हीलचेअर सुविधा","icon":"accessibility"},{"en":"Car parking","mr":"कार पार्किंग","icon":"car"},{"en":"In-house X-Ray","mr":"हॉस्पिटलमध्येच एक्स-रे","icon":"scan"},{"en":"Physiotherapy unit","mr":"फिजिओथेरपी विभाग","icon":"activity"}],"to_confirm":["OPD hours (currently an example: Mon–Sat 10–2 and 5–8)","Chief surgeon’s full name, qualification and years of experience","Physiotherapist’s name and qualification","Consultation fees","Hip replacement and arthroscopy are offered (hidden until confirmed)","Cashless insurance: which TPAs / insurers (hidden until confirmed)","Google Maps link","Logo, building and doctor photos (with consent)","Retention period for booking records (default 12 months)","Marathi wording reviewed by hospital staff"]}'::jsonb, '{"notify_whatsapp":["+918668859522"]}'::jsonb)
